package org.threeten.extra.chrono;

import static java.time.temporal.ChronoField.ALIGNED_DAY_OF_WEEK_IN_MONTH;
import static java.time.temporal.ChronoField.ALIGNED_DAY_OF_WEEK_IN_YEAR;
import static java.time.temporal.ChronoField.ALIGNED_WEEK_OF_MONTH;
import static java.time.temporal.ChronoField.ALIGNED_WEEK_OF_YEAR;
import static java.time.temporal.ChronoField.DAY_OF_MONTH;
import static java.time.temporal.ChronoField.DAY_OF_WEEK;
import static java.time.temporal.ChronoField.DAY_OF_YEAR;
import static java.time.temporal.ChronoField.EPOCH_DAY;
import static java.time.temporal.ChronoField.MONTH_OF_YEAR;
import static java.time.temporal.ChronoField.YEAR;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.time.DateTimeException;
import java.time.temporal.TemporalField;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

/**
 * Verifies that {@link Symmetry454Date#with(TemporalField, long)} rejects values that fall
 * outside the valid range for the given field, by throwing a {@link DateTimeException}.
 */
@SuppressWarnings({ "static-method" })
public class TestSymmetry454Chronology_test_with_TemporalField_badValue {

    /**
     * Each case is: a valid starting date (year, month, dayOfMonth), the field to set, and an
     * out-of-range value for that field. The field/value pairs probe the boundaries just below
     * the minimum and just above the maximum of each field's valid range.
     */
    public static Object[][] data_with_bad() {
        return new Object[][] {
            // ALIGNED_DAY_OF_WEEK_IN_MONTH: valid range is 1..7
            { 2013, 1, 1, ALIGNED_DAY_OF_WEEK_IN_MONTH, -1 },
            { 2013, 1, 1, ALIGNED_DAY_OF_WEEK_IN_MONTH, 8 },

            // ALIGNED_DAY_OF_WEEK_IN_YEAR: valid range is 1..7
            { 2013, 1, 1, ALIGNED_DAY_OF_WEEK_IN_YEAR, -1 },
            { 2013, 1, 1, ALIGNED_DAY_OF_WEEK_IN_YEAR, 8 },

            // ALIGNED_WEEK_OF_MONTH: max is 4 for 28-day months, 5 for 35-day months
            { 2013, 1, 1, ALIGNED_WEEK_OF_MONTH, -1 },
            { 2013, 1, 1, ALIGNED_WEEK_OF_MONTH, 5 },
            { 2013, 2, 1, ALIGNED_WEEK_OF_MONTH, 6 },

            // ALIGNED_WEEK_OF_YEAR: max is 52 for normal years, 53 for leap years
            { 2013, 1, 1, ALIGNED_WEEK_OF_YEAR, -1 },
            { 2013, 1, 1, ALIGNED_WEEK_OF_YEAR, 53 },
            { 2015, 1, 1, ALIGNED_WEEK_OF_YEAR, 54 },

            // DAY_OF_WEEK: valid range is 1..7
            { 2013, 1, 1, DAY_OF_WEEK, -1 },
            { 2013, 1, 1, DAY_OF_WEEK, 8 },

            // DAY_OF_MONTH: max is 28 for short months, 35 for long months
            { 2013, 1, 1, DAY_OF_MONTH, -1 },
            { 2013, 1, 1, DAY_OF_MONTH, 29 },
            { 2013, 6, 1, DAY_OF_MONTH, 29 },
            { 2013, 12, 1, DAY_OF_MONTH, 30 },
            { 2015, 12, 1, DAY_OF_MONTH, 36 },

            // DAY_OF_YEAR: max is 364 for normal years, 371 for leap years
            { 2013, 1, 1, DAY_OF_YEAR, -1 },
            { 2013, 1, 1, DAY_OF_YEAR, 365 },
            { 2015, 1, 1, DAY_OF_YEAR, 372 },

            // MONTH_OF_YEAR: valid range is 1..12
            { 2013, 1, 1, MONTH_OF_YEAR, -1 },
            { 2013, 1, 1, MONTH_OF_YEAR, 14 },
            { 2013, 1, 1, MONTH_OF_YEAR, -2 },
            { 2013, 1, 1, MONTH_OF_YEAR, 14 },

            // EPOCH_DAY: beyond the supported proleptic-year span
            { 2013, 1, 1, EPOCH_DAY, -365_961_481 },
            { 2013, 1, 1, EPOCH_DAY, 364_523_156 },

            // YEAR: supported range is -1_000_000..1_000_000
            { 2013, 1, 1, YEAR, -1_000_001 },
            { 2013, 1, 1, YEAR, 1_000_001 },
        };
    }

    @ParameterizedTest
    @MethodSource("data_with_bad")
    public void test_with_TemporalField_badValue(int year, int month, int dom, TemporalField field, long value) {
        Symmetry454Date date = Symmetry454Date.of(year, month, dom);

        assertThrows(DateTimeException.class, () -> date.with(field, value));
    }
}
